import re
def pg(t,i): return t[:i].count('=== PAGE')
for f,kws in [('BAV77QQL.txt',['TABLE 4.','TABLE 6.','TABLE 8.']),('QJ2IG6CA.txt',['Results','RSI','Eccentric deceleration','Practical Applications','Discussion']),('NAFZ3EN2.txt',['72 h','Table 3','FT:CT'])]:
